/// Canvas with straight (non-premultiplied) f32 RGBA pixels.
pub struct Canvas {
    pub width: usize,
    pub height: usize,
    pub px: Vec<Rgba>,
}

#[derive(Clone, Copy, Debug)]
pub struct RRect {
    pub x: f32,
    pub y: f32,
    pub w: f32,
    pub h: f32,
    pub r: f32,
}

impl RRect {
    /// Signed distance from point to the rounded rectangle (negative inside).
    pub fn sdf(&self, px: f32, py: f32) -> f32 {
        let r = self.r.min(self.w / 2.0).min(self.h / 2.0).max(0.0);
        let cx = self.x + self.w / 2.0;
        let cy = self.y + self.h / 2.0;
        let hx = self.w / 2.0 - r;
        let hy = self.h / 2.0 - r;
        let dx = (px - cx).abs() - hx;
        let dy = (py - cy).abs() - hy;
        let ox = dx.max(0.0);
        let oy = dy.max(0.0);
        let outside = (ox * ox + oy * oy).sqrt();
        let inside = dx.max(dy).min(0.0);
        outside + inside - r
    }
}

fn blend(dst: Rgba, src: Rgba, cov: f32) -> Rgba {
    let sa = (src.a * cov).clamp(0.0, 1.0);
    if sa <= 0.0 {
        return dst;
    }
    let da = dst.a;
    let oa = sa + da * (1.0 - sa);
    if oa <= 0.0 {
        return Rgba::new(0.0, 0.0, 0.0, 0.0);
    }
    let f = |s: f32, d: f32| (s * sa + d * da * (1.0 - sa)) / oa;
    Rgba::new(f(src.r, dst.r), f(src.g, dst.g), f(src.b, dst.b), oa)
}

impl Canvas {
    pub fn new(width: usize, height: usize) -> Canvas {
        Canvas {
            width,
            height,
            px: vec![Rgba::new(0.0, 0.0, 0.0, 0.0); width * height],
        }
    }

    #[inline]
    pub fn blend_px(&mut self, x: i32, y: i32, src: Rgba, cov: f32) {
        if x < 0 || y < 0 || x as usize >= self.width || y as usize >= self.height {
            return;
        }
        let i = y as usize * self.width + x as usize;
        self.px[i] = blend(self.px[i], src, cov);
    }

    pub fn fill_all(&mut self, c: Rgba) {
        for p in self.px.iter_mut() {
            *p = blend(*p, c, 1.0);
        }
    }

    /// Fill a rounded rectangle with anti-aliased edges.
    pub fn fill_rrect(&mut self, rr: RRect, c: Rgba) {
        let x0 = (rr.x.floor() as i32 - 1).max(0);
        let y0 = (rr.y.floor() as i32 - 1).max(0);
        let x1 = ((rr.x + rr.w).ceil() as i32 + 1).min(self.width as i32);
        let y1 = ((rr.y + rr.h).ceil() as i32 + 1).min(self.height as i32);
        for y in y0..y1 {
            for x in x0..x1 {
                let d = rr.sdf(x as f32 + 0.5, y as f32 + 0.5);
                let cov = (0.5 - d).clamp(0.0, 1.0);
                if cov > 0.0 {
                    self.blend_px(x, y, c, cov);
                }
            }
        }
    }

    /// Fill an axis-aligned rectangle (anti-aliased edges).
    pub fn fill_rect(&mut self, x: f32, y: f32, w: f32, h: f32, c: Rgba) {
        self.fill_rrect(RRect { x, y, w, h, r: 0.0 }, c);
    }

    /// Stroke the inside of a rounded rectangle with a border of `width`
    /// pixels, inset by `inset` pixels from the edge.
    pub fn stroke_rrect_inner(&mut self, rr: RRect, width: f32, inset: f32, c: Rgba) {
        let x0 = (rr.x.floor() as i32 - 1).max(0);
        let y0 = (rr.y.floor() as i32 - 1).max(0);
        let x1 = ((rr.x + rr.w).ceil() as i32 + 1).min(self.width as i32);
        let y1 = ((rr.y + rr.h).ceil() as i32 + 1).min(self.height as i32);
        let center = -(inset + width / 2.0);
        for y in y0..y1 {
            for x in x0..x1 {
                let d = rr.sdf(x as f32 + 0.5, y as f32 + 0.5);
                let cov = (width / 2.0 + 0.5 - (d - center).abs()).clamp(0.0, 1.0);
                if cov > 0.0 {
                    self.blend_px(x, y, c, cov);
                }
            }
        }
    }

    pub fn fill_circle(&mut self, cx: f32, cy: f32, r: f32, c: Rgba) {
        self.fill_rrect(
            RRect {
                x: cx - r,
                y: cy - r,
                w: 2.0 * r,
                h: 2.0 * r,
                r,
            },
            c,
        );
    }

    /// Draw a blurred, filled rounded rectangle (used for shadows).
    pub fn fill_rrect_blurred(&mut self, rr: RRect, blur: f32, c: Rgba) {
        if blur <= 0.0 {
            self.fill_rrect(rr, c);
            return;
        }
        let pad = (blur * 3.0).ceil() as i32 + 1;
        let x0 = (rr.x.floor() as i32 - pad).max(0);
        let y0 = (rr.y.floor() as i32 - pad).max(0);
        let x1 = ((rr.x + rr.w).ceil() as i32 + pad).min(self.width as i32);
        let y1 = ((rr.y + rr.h).ceil() as i32 + pad).min(self.height as i32);
        if x1 <= x0 || y1 <= y0 {
            return;
        }
        let w = (x1 - x0) as usize;
        let h = (y1 - y0) as usize;
        let mut mask = vec![0.0f32; w * h];
        for y in 0..h {
            for x in 0..w {
                let d = rr.sdf((x0 + x as i32) as f32 + 0.5, (y0 + y as i32) as f32 + 0.5);
                mask[y * w + x] = (0.5 - d).clamp(0.0, 1.0);
            }
        }
        let mask = gaussian_blur(&mask, w, h, blur);
        for y in 0..h {
            for x in 0..w {
                let cov = mask[y * w + x];
                if cov > 0.0005 {
                    self.blend_px(x0 + x as i32, y0 + y as i32, c, cov);
                }
            }
        }
    }

    /// Composite a coverage bitmap (e.g. a glyph) with the given color.
    pub fn draw_coverage(&mut self, left: i32, top: i32, w: usize, h: usize, cov: &[f32], c: Rgba) {
        for y in 0..h {
            let py = top + y as i32;
            if py < 0 || py >= self.height as i32 {
                continue;
            }
            for x in 0..w {
                let v = cov[y * w + x];
                if v > 0.001 {
                    self.blend_px(left + x as i32, py, c, v);
                }
            }
        }
    }

    /// Linear gradient fill across the whole canvas.
    pub fn fill_linear_gradient(&mut self, start: (f32, f32), end: (f32, f32), stops: &[(f32, Rgba)]) {
        if stops.is_empty() {
            return;
        }
        let dx = end.0 - start.0;
        let dy = end.1 - start.1;
        let len2 = dx * dx + dy * dy;
        let mut sorted: Vec<(f32, Rgba)> = stops.to_vec();
        sorted.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
        for y in 0..self.height {
            for x in 0..self.width {
                let px = x as f32 + 0.5;
                let py = y as f32 + 0.5;
                let t = if len2 <= 0.0 {
                    0.0
                } else {
                    (((px - start.0) * dx + (py - start.1) * dy) / len2).clamp(0.0, 1.0)
                };
                let c = sample_stops(&sorted, t);
                let i = y * self.width + x;
                self.px[i] = blend(self.px[i], c, 1.0);
            }
        }
    }

    /// Draw another canvas (image) scaled to the destination rectangle.
    pub fn draw_image(&mut self, img: &Canvas, dx: f32, dy: f32, dw: f32, dh: f32) {
        if img.width == 0 || img.height == 0 || dw <= 0.0 || dh <= 0.0 {
            return;
        }
        let x0 = dx.floor().max(0.0) as i32;
        let y0 = dy.floor().max(0.0) as i32;
        let x1 = ((dx + dw).ceil() as i32).min(self.width as i32);
        let y1 = ((dy + dh).ceil() as i32).min(self.height as i32);
        for y in y0..y1 {
            for x in x0..x1 {
                // coverage of this pixel by the destination rect
                let cx = ((x as f32 + 1.0).min(dx + dw) - (x as f32).max(dx)).clamp(0.0, 1.0);
                let cy = ((y as f32 + 1.0).min(dy + dh) - (y as f32).max(dy)).clamp(0.0, 1.0);
                let cov = cx * cy;
                if cov <= 0.0 {
                    continue;
                }
                let u = ((x as f32 + 0.5 - dx) / dw * img.width as f32).floor().clamp(0.0, img.width as f32 - 1.0) as usize;
                let v = ((y as f32 + 0.5 - dy) / dh * img.height as f32).floor().clamp(0.0, img.height as f32 - 1.0) as usize;
                let c = img.px[v * img.width + u];
                self.blend_px(x, y, c, cov);
            }
        }
    }

    pub fn to_rgba8(&self) -> Vec<u8> {
        let mut out = Vec::with_capacity(self.width * self.height * 4);
        for p in &self.px {
            let q = |v: f32| (v.clamp(0.0, 1.0) * 255.0 + 0.5) as u8;
            out.push(q(p.r));
            out.push(q(p.g));
            out.push(q(p.b));
            out.push(q(p.a));
        }
        out
    }
}

fn sample_stops(stops: &[(f32, Rgba)], t: f32) -> Rgba {
    if t <= stops[0].0 {
        return stops[0].1;
    }
    for i in 1..stops.len() {
        let (p0, c0) = stops[i - 1];
        let (p1, c1) = stops[i];
        if t <= p1 {
            let f = if p1 > p0 { (t - p0) / (p1 - p0) } else { 1.0 };
            return Rgba::new(
                c0.r + (c1.r - c0.r) * f,
                c0.g + (c1.g - c0.g) * f,
                c0.b + (c1.b - c0.b) * f,
                c0.a + (c1.a - c0.a) * f,
            );
        }
    }
    stops[stops.len() - 1].1
}

/// Separable gaussian blur of a single-channel f32 image.
pub fn gaussian_blur(src: &[f32], w: usize, h: usize, sigma: f32) -> Vec<f32> {
    let radius = (sigma * 3.0).ceil() as i32;
    let mut kernel = Vec::with_capacity((2 * radius + 1) as usize);
    let mut sum = 0.0;
    for i in -radius..=radius {
        let v = (-(i * i) as f32 / (2.0 * sigma * sigma)).exp();
        kernel.push(v);
        sum += v;
    }
    for k in kernel.iter_mut() {
        *k /= sum;
    }
    let mut tmp = vec![0.0f32; w * h];
    for y in 0..h {
        for x in 0..w {
            let mut acc = 0.0;
            for (ki, k) in kernel.iter().enumerate() {
                let sx = x as i32 + ki as i32 - radius;
                if sx >= 0 && (sx as usize) < w {
                    acc += src[y * w + sx as usize] * k;
                }
            }
            tmp[y * w + x] = acc;
        }
    }
    let mut out = vec![0.0f32; w * h];
    for y in 0..h {
        for x in 0..w {
            let mut acc = 0.0;
            for (ki, k) in kernel.iter().enumerate() {
                let sy = y as i32 + ki as i32 - radius;
                if sy >= 0 && (sy as usize) < h {
                    acc += tmp[sy as usize * w + x] * k;
                }
            }
            out[y * w + x] = acc;
        }
    }
    out
}
