//! Minimal PNG encoder and decoder.

use flate2::read::ZlibDecoder;
use flate2::write::ZlibEncoder;
use flate2::Compression;
use std::io::{Read, Write};

fn chunk(out: &mut Vec<u8>, typ: &[u8; 4], data: &[u8]) {
    out.extend_from_slice(&(data.len() as u32).to_be_bytes());
    let mut crc = crc32fast::Hasher::new();
    crc.update(typ);
    crc.update(data);
    out.extend_from_slice(typ);
    out.extend_from_slice(data);
    out.extend_from_slice(&crc.finalize().to_be_bytes());
}

/// Encode 8-bit RGBA pixels as a PNG.
pub fn encode_rgba(width: u32, height: u32, rgba: &[u8]) -> Vec<u8> {
    let stride = width as usize * 4;
    let mut raw = Vec::with_capacity((stride + 1) * height as usize);
    let mut prev: Vec<u8> = vec![0; stride];
    for y in 0..height as usize {
        let row = &rgba[y * stride..(y + 1) * stride];
        // "Up" filter: cheap and compresses well for flat regions
        raw.push(2);
        for i in 0..stride {
            raw.push(row[i].wrapping_sub(prev[i]));
        }
        prev.copy_from_slice(row);
    }
    let mut enc = ZlibEncoder::new(Vec::new(), Compression::default());
    enc.write_all(&raw).expect("zlib");
    let idat = enc.finish().expect("zlib");

    let mut out = Vec::with_capacity(idat.len() + 64);
    out.extend_from_slice(b"\x89PNG\r\n\x1a\n");
    let mut ihdr = Vec::with_capacity(13);
    ihdr.extend_from_slice(&width.to_be_bytes());
    ihdr.extend_from_slice(&height.to_be_bytes());
    ihdr.extend_from_slice(&[8, 6, 0, 0, 0]);
    chunk(&mut out, b"IHDR", &ihdr);
    chunk(&mut out, b"IDAT", &idat);
    chunk(&mut out, b"IEND", &[]);
    out
}

pub struct DecodedImage {
    pub width: u32,
    pub height: u32,
    /// 8-bit RGBA
    pub rgba: Vec<u8>,
}

const ERR_EOF: &str = "Unexpected end of data before image end.";
const ERR_SIG: &str = "Invalid PNG signature.";

fn rd32(d: &[u8], o: usize) -> u32 {
    u32::from_be_bytes([d[o], d[o + 1], d[o + 2], d[o + 3]])
}

/// Decode a PNG into 8-bit RGBA.
pub fn decode(data: &[u8]) -> Result<DecodedImage, String> {
    if data.len() < 8 {
        return Err(ERR_EOF.to_string());
    }
    if &data[..8] != b"\x89PNG\r\n\x1a\n" {
        return Err(ERR_SIG.to_string());
    }
    let mut pos = 8;
    let mut width = 0u32;
    let mut height = 0u32;
    let mut bit_depth = 0u8;
    let mut color_type = 0u8;
    let mut interlace = 0u8;
    let mut palette: Vec<[u8; 3]> = Vec::new();
    let mut trns: Vec<u8> = Vec::new();
    let mut idat: Vec<u8> = Vec::new();
    let mut seen_ihdr = false;
    let mut seen_iend = false;
    while pos + 8 <= data.len() {
        let len = rd32(data, pos) as usize;
        let typ = &data[pos + 4..pos + 8];
        if pos + 12 + len > data.len() {
            return Err(ERR_EOF.to_string());
        }
        let body = &data[pos + 8..pos + 8 + len];
        match typ {
            b"IHDR" => {
                if len < 13 {
                    return Err("Invalid IHDR chunk.".to_string());
                }
                width = rd32(body, 0);
                height = rd32(body, 4);
                bit_depth = body[8];
                color_type = body[9];
                interlace = body[12];
                seen_ihdr = true;
            }
            b"PLTE" => {
                for c in body.chunks_exact(3) {
                    palette.push([c[0], c[1], c[2]]);
                }
            }
            b"tRNS" => trns = body.to_vec(),
            b"IDAT" => idat.extend_from_slice(body),
            b"IEND" => {
                seen_iend = true;
                break;
            }
            _ => {}
        }
        pos += 12 + len;
    }
    if !seen_ihdr {
        return Err(ERR_EOF.to_string());
    }
    if !seen_iend && idat.is_empty() {
        return Err(ERR_EOF.to_string());
    }
    if interlace != 0 {
        return Err("Interlaced PNG images are not supported.".to_string());
    }
    if width == 0 || height == 0 {
        return Err("Invalid image dimensions.".to_string());
    }
    let channels = match color_type {
        0 => 1,
        2 => 3,
        3 => 1,
        4 => 2,
        6 => 4,
        _ => return Err("Invalid color type.".to_string()),
    };
    let bits_pp = channels * bit_depth as usize;
    let stride = (width as usize * bits_pp + 7) / 8;
    let bpp = ((bits_pp + 7) / 8).max(1);
    let mut raw = Vec::with_capacity((stride + 1) * height as usize);
    let mut dec = ZlibDecoder::new(&idat[..]);
    if dec.read_to_end(&mut raw).is_err() {
        return Err("Corrupt deflate stream.".to_string());
    }
    if raw.len() < (stride + 1) * height as usize {
        return Err(ERR_EOF.to_string());
    }
    // unfilter
    let mut img = vec![0u8; stride * height as usize];
    let mut prev = vec![0u8; stride];
    for y in 0..height as usize {
        let ft = raw[y * (stride + 1)];
        let line = &raw[y * (stride + 1) + 1..(y + 1) * (stride + 1)];
        let mut cur = vec![0u8; stride];
        for i in 0..stride {
            let a = if i >= bpp { cur[i - bpp] as i32 } else { 0 };
            let b = prev[i] as i32;
            let c = if i >= bpp { prev[i - bpp] as i32 } else { 0 };
            let x = line[i] as i32;
            let v = match ft {
                0 => x,
                1 => x + a,
                2 => x + b,
                3 => x + ((a + b) >> 1),
                4 => {
                    let p = a + b - c;
                    let pa = (p - a).abs();
                    let pb = (p - b).abs();
                    let pc = (p - c).abs();
                    let pr = if pa <= pb && pa <= pc {
                        a
                    } else if pb <= pc {
                        b
                    } else {
                        c
                    };
                    x + pr
                }
                _ => return Err("Invalid filter method.".to_string()),
            };
            cur[i] = (v & 0xff) as u8;
        }
        img[y * stride..(y + 1) * stride].copy_from_slice(&cur);
        prev = cur;
    }
    // expand to RGBA8
    let mut rgba = Vec::with_capacity(width as usize * height as usize * 4);
    let sample = |row: &[u8], idx: usize| -> u16 {
        // idx-th sample in the row at bit_depth
        match bit_depth {
            8 => row[idx] as u16,
            16 => u16::from_be_bytes([row[idx * 2], row[idx * 2 + 1]]),
            1 | 2 | 4 => {
                let bd = bit_depth as usize;
                let bit = idx * bd;
                let byte = row[bit / 8];
                let shift = 8 - bd - (bit % 8);
                ((byte >> shift) & ((1u8 << bd) - 1)) as u16
            }
            _ => 0,
        }
    };
    let to8 = |v: u16| -> u8 {
        match bit_depth {
            8 => v as u8,
            16 => (v >> 8) as u8,
            1 => (v * 255) as u8,
            2 => (v * 85) as u8,
            4 => (v * 17) as u8,
            _ => 0,
        }
    };
    for y in 0..height as usize {
        let row = &img[y * stride..(y + 1) * stride];
        for x in 0..width as usize {
            match color_type {
                0 => {
                    let g = sample(row, x);
                    let g8 = to8(g);
                    let a = if trns.len() >= 2 && u16::from_be_bytes([trns[0], trns[1]]) == g { 0 } else { 255 };
                    rgba.extend_from_slice(&[g8, g8, g8, a]);
                }
                2 => {
                    let r = sample(row, x * 3);
                    let g = sample(row, x * 3 + 1);
                    let b = sample(row, x * 3 + 2);
                    let a = if trns.len() >= 6
                        && u16::from_be_bytes([trns[0], trns[1]]) == r
                        && u16::from_be_bytes([trns[2], trns[3]]) == g
                        && u16::from_be_bytes([trns[4], trns[5]]) == b
                    {
                        0
                    } else {
                        255
                    };
                    rgba.extend_from_slice(&[to8(r), to8(g), to8(b), a]);
                }
                3 => {
                    let i = sample(row, x) as usize;
                    let c = palette.get(i).copied().unwrap_or([0, 0, 0]);
                    let a = trns.get(i).copied().unwrap_or(255);
                    rgba.extend_from_slice(&[c[0], c[1], c[2], a]);
                }
                4 => {
                    let g = to8(sample(row, x * 2));
                    let a = to8(sample(row, x * 2 + 1));
                    rgba.extend_from_slice(&[g, g, g, a]);
                }
                _ => {
                    let r = to8(sample(row, x * 4));
                    let g = to8(sample(row, x * 4 + 1));
                    let b = to8(sample(row, x * 4 + 2));
                    let a = to8(sample(row, x * 4 + 3));
                    rgba.extend_from_slice(&[r, g, b, a]);
                }
            }
        }
    }
    Ok(DecodedImage { width, height, rgba })
}
