//! Emulation of library panics: prints a Rust-style panic message with a
//! given source location and exits with status 101.

use std::io::Write;

pub fn panic_at(location: &str, msg: &str) -> ! {
    let _ = std::io::stdout().flush();
    let pid = std::process::id();
    let mut err = std::io::stderr().lock();
    let _ = writeln!(err, "\nthread 'main' ({}) panicked at {}:\n{}", pid, location, msg);
    match std::env::var("RUST_BACKTRACE") {
        Ok(v) if v != "0" => {
            let _ = writeln!(err, "stack backtrace:");
        }
        _ => {
            let _ = writeln!(
                err,
                "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace"
            );
        }
    }
    let _ = err.flush();
    std::process::exit(101);
}

