use crate::raster::Rgba;

const LOC_INVALID: &str = "core/src/utils/color.rs:32:13";
const LOC_UNWRAP: &str = "core/src/utils/color.rs:41:85";

fn parse_pair(s: &str) -> u8 {
    match i64::from_str_radix(s, 16) {
        Ok(v) => v as u8,
        Err(e) => {
            let kind = match e.kind() {
                std::num::IntErrorKind::Empty => "Empty",
                std::num::IntErrorKind::InvalidDigit => "InvalidDigit",
                std::num::IntErrorKind::PosOverflow => "PosOverflow",
                std::num::IntErrorKind::NegOverflow => "NegOverflow",
                std::num::IntErrorKind::Zero => "Zero",
                _ => "InvalidDigit",
