//! Embedded fonts and text drawing helpers.

use crate::font::Font;
use crate::raster::{Canvas, Rgba};
use std::sync::OnceLock;

static MONO_DATA: &[u8] = include_bytes!("../assets/fonts/DejaVuSansMono.ttf");
static SANS_DATA: &[u8] = include_bytes!("../assets/fonts/DejaVuSans.ttf");

pub struct Fonts {
    pub mono: Font,
    pub sans: Font,
}

static FONTS: OnceLock<Fonts> = OnceLock::new();

pub fn fonts() -> &'static Fonts {
    FONTS.get_or_init(|| Fonts {
        mono: Font::parse(MONO_DATA).expect("embedded mono font"),
        sans: Font::parse(SANS_DATA).expect("embedded sans font"),
    })
}

/// Advance of one monospace cell relative to the font size.
pub const CELL_EM: f32 = 0.5859375;

/// Number of monospace cells a character occupies.
pub fn cell_width(c: char) -> usize {
    let cp = c as u32;
    if c == '\t' {
        return 2;
    }
    if cp < 0x20 || (0x7f..0xa0).contains(&cp) {
        return 0;
    }
    // Zero-width combining marks and joiners
    if (0x0300..0x0370).contains(&cp) || cp == 0x200b || cp == 0x200c || cp == 0x200d || cp == 0xfe0f {
        return 0;
    }
    // East Asian wide / fullwidth ranges (approximation)
    if (0x1100..=0x115f).contains(&cp)
        || (0x2e80..=0x303e).contains(&cp)
        || (0x3041..=0x33ff).contains(&cp)
        || (0x3400..=0x4dbf).contains(&cp)
        || (0x4e00..=0x9fff).contains(&cp)
        || (0xa000..=0xa4cf).contains(&cp)
        || (0xac00..=0xd7a3).contains(&cp)
        || (0xf900..=0xfaff).contains(&cp)
        || (0xfe30..=0xfe4f).contains(&cp)
        || (0xff00..=0xff60).contains(&cp)
        || (0xffe0..=0xffe6).contains(&cp)
        || (0x1f300..=0x1f64f).contains(&cp)
        || (0x1f900..=0x1f9ff).contains(&cp)
        || (0x20000..=0x3fffd).contains(&cp)
    {
        return 2;
    }
    1
}

/// Width of a string in monospace cells.
pub fn cells(s: &str) -> usize {
    s.chars().map(cell_width).sum()
}

impl Fonts {
    /// Draw monospace text. `x`, `baseline` and `size` are in 1x units and
    /// are multiplied by `scale`. Returns the number of cells consumed.
    pub fn draw_mono(&self, canvas: &mut Canvas, x: f32, baseline: f32, text: &str, size: f32, color: Rgba, scale: f32) -> usize {
        let cell = size * CELL_EM;
        let mut cx = x;
        let mut total = 0usize;
        for ch in text.chars() {
            let w = cell_width(ch);
            if w == 0 {
                continue;
            }
            let gid = self.mono.glyph_index(ch);
            if gid != 0 {
                // squeeze the glyph horizontally so the advance matches the cell
                let natural = self.mono.advance(gid) / self.mono.units_per_em();
                let sx = if natural > 0.0 { (CELL_EM * w as f32 / natural).min(1.0) } else { 1.0 };
                self.draw_glyph(&self.mono, canvas, gid, cx, baseline, size, sx, color, scale);
            } else {
                let gid2 = self.sans.glyph_index(ch);
                if gid2 != 0 {
                    let natural = self.sans.advance(gid2) / self.sans.units_per_em();
                    let sx = if natural > 0.0 { (CELL_EM * w as f32 / natural).min(1.0) } else { 1.0 };
                    self.draw_glyph(&self.sans, canvas, gid2, cx, baseline, size, sx, color, scale);
                }
            }
            cx += cell * w as f32;
            total += w;
        }
        total
    }

    /// Measure proportional (sans) text width in 1x units.
    pub fn measure_sans(&self, text: &str, size: f32) -> f32 {
        let upem = self.sans.units_per_em();
        text.chars()
            .map(|c| {
                let gid = self.sans.glyph_index(c);
                if gid == 0 {
                    size * 0.6
                } else {
                    self.sans.advance(gid) / upem * size
                }
            })
            .sum()
    }

    /// Draw proportional text starting at `x`.
    pub fn draw_sans(&self, canvas: &mut Canvas, x: f32, baseline: f32, text: &str, size: f32, color: Rgba, scale: f32) {
        let upem = self.sans.units_per_em();
        let mut cx = x;
        for c in text.chars() {
            let gid = self.sans.glyph_index(c);
            if gid == 0 {
                cx += size * 0.6;
                continue;
            }
            self.draw_glyph(&self.sans, canvas, gid, cx, baseline, size, 1.0, color, scale);
            cx += self.sans.advance(gid) / upem * size;
        }
    }

