                lines.push(Line {
                    text: format!("> {}", b.command),
                    height: EXEC_LINE_HEIGHT,
                    kind: LineKind::Prompt,
                });
                for o in &b.output {
                    lines.push(Line {
                        text: o.clone(),
                        height: EXEC_LINE_HEIGHT,
                        kind: LineKind::Output,
                    });
                }
            }
        }
        RenderKind::Image(img) => {
            image_size = Some((img.width as f32, img.height as f32));
        }
    }

    let cell = CODE_FONT_SIZE * CELL_EM;
    let ln_digits = opts.line_numbers.as_ref().map(|(start, _)| {
        let last = (*start as u64 + lines.len().max(1) as u64 - 1).min(u32::MAX as u64) as u32;
        digits(last)
    });
    let ln_col = ln_digits.map(|d| d as f32 * 9.0 + 31.0 / 3.0).unwrap_or(0.0);
    let code_w = lines.iter().map(|l| text::cells(&l.text) as f32 * cell).fold(0.0, f32::max);
    let breadcrumbs_w = opts
        .breadcrumbs
        .as_ref()
        .map(|(p, _)| p.chars().count() as f32 * 8.0)
        .unwrap_or(0.0);
    let title_w = opts
        .title
        .as_ref()
        .map(|(t, _)| f.measure_sans(t, TITLE_FONT_SIZE) + if opts.mac_window_bar { 62.0 } else { 0.0 })
        .unwrap_or(0.0);

    let has_watermark = opts.watermark.is_some() && opts.margin_y >= WATERMARK_MIN_MARGIN;

    let (window_w, window_h) = match image_size {
        Some((iw, ih)) => (iw, ih),
        None => {
            let content_w = (ln_col + code_w).max(breadcrumbs_w).max(title_w);
            let w = (2.0 * PAD_X + content_w).max(MIN_WINDOW_WIDTH);
            let mut h = PAD_TOP + PAD_BOTTOM;
            if opts.mac_window_bar {
                h += MAC_BAR_HEIGHT;
            } else if opts.title.is_some() {
                h += TITLE_ROW_HEIGHT;
            }
            if opts.breadcrumbs.is_some() {
                h += BREADCRUMBS_HEIGHT;
            }
            h += lines.iter().map(|l| l.height).sum::<f32>();
            (w, h)
        }
    };
    let img_w = window_w + 2.0 * opts.margin_x;
    let img_h = window_h + 2.0 * opts.margin_y + if has_watermark { WATERMARK_HEIGHT } else { 0.0 };
    let pw = img_w * s;
    let ph = img_h * s;
    let pw_u = if pw.is_finite() && pw > 0.0 { pw as u32 } else { 0 };
    let ph_u = if ph.is_finite() && ph > 0.0 { ph as u32 } else { 0 };
    if pw_u == 0 || ph_u == 0 || pw_u > 1 << 15 || ph_u > 1 << 15 {
        fatal::panic_at("core/src/components/container.rs:34:10", fatal::UNWRAP_NONE);
    }
    let mut canvas = Canvas::new(pw_u as usize, ph_u as usize);

    // ---- background ----
    match &opts.background {
        BackgroundSpec::Solid(c) => {
            let col = parse_hex(c);
            canvas.fill_all(col);
        }
        BackgroundSpec::Gradient { start, end, stops } => {
            if stops.is_empty() {
                fatal::panic_at("core/src/components/background.rs:80:18", fatal::UNWRAP_NONE);
            }
            let st: Vec<(f32, Rgba)> = stops.iter().map(|(p, c)| (*p, parse_hex(c))).collect();
            let sx = start.0.resolve(img_w) * s;
            let sy = start.1.resolve(img_h) * s;
            let ex = end.0.resolve(img_w) * s;
            let ey = end.1.resolve(img_h) * s;
            canvas.fill_linear_gradient((sx, sy), (ex, ey), &st);
        }
    }

    let wx = opts.margin_x;
    let wy = opts.margin_y;
    let radius = if image_size.is_some() { 0.0 } else { opts.radius };
    let window = RRect {
        x: wx * s,
        y: wy * s,
        w: window_w * s,
        h: window_h * s,
        r: radius * s,
    };

    // ---- shadow ----
    let shadow_color = parse_hex(&opts.shadow_color);
    if opts.shadow_radius > 0.0 && shadow_color.a > 0.0 {
        let blur = opts.shadow_radius / 2.0 * s;
        let shadow_rect = RRect {
            y: window.y + opts.shadow_radius / 2.0 * s,
            ..window
        };
        canvas.fill_rrect_blurred(shadow_rect, blur, shadow_color);
    }

    // ---- image kind ----
    if let RenderKind::Image(img) = &opts.kind {
        canvas.draw_image(img, window.x, window.y, window.w, window.h);
        if has_watermark {
            draw_watermark(&mut canvas, opts, img_w, wy + window_h, s);
        }
        return canvas;
    }

    // ---- window ----
    canvas.fill_rrect(window, WINDOW_BG);
    if let Some((bw, bc)) = &opts.border {
        let bcol = parse_hex(bc);
        if *bw > 0.0 {
            canvas.stroke_rrect_inner(window, bw * s, 1.0 * s, bcol);
        }
    }

    let mut cy = wy + PAD_TOP; // current y (1x) inside the window
    if opts.mac_window_bar {
        let dot_r = 6.0;
        let colors = [
            Rgba::from_u8(0xff, 0x5e, 0x57, 0xff),
            Rgba::from_u8(0xff, 0xba, 0x2e, 0xff),
            Rgba::from_u8(0x2b, 0xc8, 0x41, 0xff),
        ];
        for (i, c) in colors.iter().enumerate() {
            let cx = wx + PAD_X - 0.5 + dot_r + i as f32 * 16.0;
            let cyy = wy + 21.5;
            canvas.fill_circle(cx * s, cyy * s, dot_r * s, *c);
        }
        if let Some((title, color)) = &opts.title {
            let col = parse_hex(color);
            let tw = f.measure_sans(title, TITLE_FONT_SIZE);
            let tx = wx + (window_w - tw) / 2.0;
            f.draw_sans(&mut canvas, tx, wy + 23.0, title, TITLE_FONT_SIZE, col, s);
        }
        cy += MAC_BAR_HEIGHT;
    } else if let Some((title, color)) = &opts.title {
        let col = parse_hex(color);
        let tw = f.measure_sans(title, TITLE_FONT_SIZE);
        let tx = wx + (window_w - tw) / 2.0;
        f.draw_sans(&mut canvas, tx, cy + 11.0, title, TITLE_FONT_SIZE, col, s);
        cy += TITLE_ROW_HEIGHT;
    }

    if let Some((path, color)) = &opts.breadcrumbs {
        let col = parse_hex(color);
        f.draw_mono(&mut canvas, wx + PAD_X, cy + 11.0, path, BREADCRUMBS_FONT_SIZE, col, s);
        cy += BREADCRUMBS_HEIGHT;
    }

    // line tops
    let mut tops = Vec::with_capacity(lines.len());
    let mut y = cy;
    for l in &lines {
        tops.push(y);
        y += l.height;
    }

    // ---- highlight bands ----
    for h in &opts.highlights {
        let col = parse_hex(&h.color);
        if h.from >= lines.len() {
            continue;
        }
        let to = h.to.min(lines.len() - 1);
        if to < h.from {
            continue;
        }
        let y0 = tops[h.from];
        let y1 = tops[to] + lines[to].height;
        canvas.fill_rect((wx + 2.0) * s, y0 * s, (window_w - 4.0) * s, (y1 - y0) * s, col);
    }

    // ---- line numbers ----
    if let Some((start, color)) = &opts.line_numbers {
        let col = parse_hex(color);
        let d = ln_digits.unwrap_or(1);
        for (i, l) in lines.iter().enumerate() {
            let n = (*start as u64 + i as u64).min(u32::MAX as u64);
            let txt = n.to_string();
            let right = wx + PAD_X + d as f32 * 9.0 - (9.0 - cell);
            let x = right - txt.len() as f32 * cell;
            let baseline = tops[i] + l.height - 5.0;
            f.draw_mono(&mut canvas, x, baseline, &txt, CODE_FONT_SIZE, col, s);
        }
    }

    // ---- text ----
    let text_x = wx + PAD_X + ln_col;
    let spans = match &opts.kind {
        RenderKind::Code { lang, .. } => highlight::highlight(&code_lines, *lang),
        _ => Vec::new(),
    };
    let prompt_col = Rgba::from_u8(0xf7, 0x8f, 0xb3, 0xff);
    let cmd_col = Rgba::from_u8(0x98, 0xc3, 0x79, 0xff);
    let arg_col = Rgba::from_u8(0xff, 0xff, 0xff, 0xff);
    let out_col = Rgba::from_u8(0x97, 0x9e, 0xab, 0xff);
    for (i, l) in lines.iter().enumerate() {
        let baseline = tops[i] + l.height - 5.0;
        match &l.kind {
            LineKind::Code(idx) => {
                let line_spans = spans.get(*idx);
                let mut x = text_x;
                match line_spans {
                    Some(sp) => {
                        for span in sp {
                            let piece = &l.text[span.start..span.end];
                            let n = f.draw_mono(&mut canvas, x, baseline, piece, CODE_FONT_SIZE, span.color, s);
                            x += n as f32 * cell;
                        }
                    }
                    None => {
                        f.draw_mono(&mut canvas, x, baseline, &l.text, CODE_FONT_SIZE, highlight::FG, s);
                    }
                }
            }
            LineKind::Prompt => {
                let mut x = text_x;
                let n = f.draw_mono(&mut canvas, x, baseline, "> ", CODE_FONT_SIZE, prompt_col, s);
                x += n as f32 * cell;
                let cmd = &l.text[2..];
                let (name, rest) = match cmd.find(' ') {
                    Some(p) => (&cmd[..p], &cmd[p..]),
                    None => (cmd, ""),
                };
                let n = f.draw_mono(&mut canvas, x, baseline, name, CODE_FONT_SIZE, cmd_col, s);
                x += n as f32 * cell;
                f.draw_mono(&mut canvas, x, baseline, rest, CODE_FONT_SIZE, arg_col, s);
            }
            LineKind::Output => {
                f.draw_mono(&mut canvas, text_x, baseline, &l.text, CODE_FONT_SIZE, out_col, s);
            }
        }
    }

    // ---- watermark ----
    if has_watermark {
        draw_watermark(&mut canvas, opts, img_w, wy + window_h, s);
    }
    canvas
}

fn draw_watermark(canvas: &mut Canvas, opts: &RenderOpts, img_w: f32, window_bottom: f32, s: f32) {
    if let Some((content, color)) = &opts.watermark {
        let col = parse_hex(color);
        let f = fonts();
        let tw = f.measure_sans(content, WATERMARK_FONT_SIZE);
        let x = (img_w - tw) / 2.0;
        let baseline = window_bottom + 82.0 - 10.0;
        f.draw_sans(canvas, x, baseline, content, WATERMARK_FONT_SIZE, col, s);
    }
}
EOF
echo ok

