fn run(m: &clap::ArgMatches) -> Result<(), String> {
    let cfg = config::load(m.get_one::<String>("config").map(|s| s.as_str()))?;
    let sc = cfg.snapshot_config.clone();
    let silent = m.get_flag("silent");
    let output = m.get_one::<String>("output").cloned().unwrap_or_default();
    let is_ascii = m.get_one::<String>("type").map(|t| t == "ascii").unwrap_or(false);

    // ---- content ----
    let content = input::get_content(m)?;

    let mut kind: Option<RenderKind> = None;
    let mut highlights: Vec<Highlight> = Vec::new();
    let mut code_file_path: Option<String> = None;
    let mut code_from_file = false;

