        Content::Code { code, file_path, from_file } => {
            let all_lines: Vec<&str> = code.lines().collect();
            let total = all_lines.len();
            let range = match m.get_one::<String>("range") {
                Some(r) => Some(input::parse_range(r, total)?),
                None => None,
            };
            let cut: Vec<&str> = match &range {
                Some(r) => input::apply_range(&all_lines, r),
                None => all_lines.clone(),
            };
            let joined = cut.join("\n");
            let normalized = input::normalize_code(&joined);
            let mut lines: Vec<String> = normalized.lines().map(|s| s.to_string()).collect();
            if lines.is_empty() {
                lines.push(String::new());
            }
            let check_range = range.unwrap_or(LineRange { start: 1, end: total });
            let relative = m.get_flag("relative_highlight_range");
            let base = check_range.lo();

            // raw highlight lines (JSON)
            if let Some(raw) = m.get_one::<String>("raw_highlight_lines") {
                let parsed: Vec<input::HighlightLine> =
                    serde_json::from_str(raw).map_err(|e| e.to_string())?;
                for h in parsed {
                    let (a, b, c) = match h {
                        input::HighlightLine::Single(a, c) => (a, a, c),
                        input::HighlightLine::Range(a, b, c) => (a, b, c),
                    };
                    let lo = a.min(b) as usize;
                    let hi = a.max(b) as usize;
                    highlights.push(Highlight {
                        from: lo.saturating_sub(1),
                        to: hi.saturating_sub(1),
                        color: c,
                    });
                }
            }
            let to_display = |lo: usize, hi: usize| -> (usize, usize) {
                if relative {
                    (lo, hi)
                } else {
                    (lo.saturating_sub(base), hi.saturating_sub(base))
                }
            };
            if let Some(hr) = m.get_one::<String>("highlight_range") {
                let hl = input::parse_range(hr, total)?;
                let (lo, hi) = input::check_highlight(&hl, &check_range, relative)?;
                let (f, t) = to_display(lo, hi);
                let color = m.get_one::<String>("highlight_range_color").cloned().unwrap_or_default();
                highlights.push(Highlight { from: f, to: t, color });
            }
            if let Some(dl) = m.get_many::<String>("delete_line") {
                let color = m.get_one::<String>("delete_line_color").cloned().unwrap_or_default();
                for d in dl {
                    let n = d.parse::<usize>().map_err(|e| e.to_string())?;
                    let hl = LineRange { start: n, end: n };
                    let (lo, hi) = input::check_highlight(&hl, &check_range, relative)?;
                    let (f, t) = to_display(lo, hi);
                    highlights.push(Highlight { from: f, to: t, color: color.clone() });
                }
            }
            if let Some(al) = m.get_many::<String>("add_line") {
                let color = m.get_one::<String>("add_line_color").cloned().unwrap_or_default();
                for a in al {
                    let n = a.parse::<usize>().map_err(|e| e.to_string())?;
                    let hl = LineRange { start: n, end: n };
                    let (lo, hi) = input::check_highlight(&hl, &check_range, relative)?;
                    let (f, t) = to_display(lo, hi);
                    highlights.push(Highlight { from: f, to: t, color: color.clone() });
                }
            }
            let lang = match m.get_one::<String>("language") {
                Some(l) => highlight::detect_from_name(l),
                None => file_path.as_deref().map(highlight::detect_from_path).unwrap_or(highlight::Lang::Plain),
            };
            code_file_path = file_path;
            code_from_file = from_file;
            kind = Some(RenderKind::Code { lines, lang });
        }
        Content::Execute(blocks) => {
            let bs = blocks
                .into_iter()
                .map(|b| ExecBlock {
                    command: b.command.replace('\t', "  "),
                    output: input::output_lines(&b.output),
                })
                .collect();
            kind = Some(RenderKind::Exec(bs));
        }
        Content::Image(img) => {
            let mut c = raster::Canvas::new(img.width as usize, img.height as usize);
            for (i, p) in c.px.iter_mut().enumerate() {
                let o = i * 4;
                *p = raster::Rgba::from_u8(img.rgba[o], img.rgba[o + 1], img.rgba[o + 2], img.rgba[o + 3]);
