            return Err(input::CLIPBOARD_ERROR.to_string());
        }
        messages::warn("ASCII snapshot only supports copying to clipboard");
        if cfg.print_eggs {
            eggs::print_egg();
        }
        return Ok(());
    }

    // ---- theme ----
    let theme = m
        .get_one::<String>("code_theme")
        .cloned()
        .or_else(|| sc.theme.clone())
        .unwrap_or_else(|| "candy".to_string());
    if theme != "candy" {
        return Err(format!("Cannot find {} theme", theme));
    }

