    if let RenderKind::Code { .. } = &kind {
        if m.get_one::<String>("language").is_none() && !code_from_file {
            if let Some(p) = &code_file_path {
                if !langs::is_known_path(p) && std::fs::File::open(p).is_err() {
                    return Err(format!("No such file {}", p));
                }
            }
        }
    }

