    let window_present = sc.window.is_some();
    let window = sc.window.clone().unwrap_or_default();
    let margin_x = m.get_one::<f32>("margin_x").copied().unwrap_or(window.margin.x);
    let margin_y = m.get_one::<f32>("margin_y").copied().unwrap_or(window.margin.y);
    let mac_window_bar = m.get_one::<bool>("mac_window_bar").copied().unwrap_or(window.mac_window_bar);
    let shadow_radius = m.get_one::<f32>("shadow_radius").copied().unwrap_or(window.shadow.radius);
    let shadow_color = m.get_one::<String>("shadow_color").cloned().unwrap_or(window.shadow.color.clone());
    let border = if m.get_flag("has_border") {
        let c = m.get_one::<String>("border_color").cloned().unwrap_or_default();
        let w = if window.border.width > 0.0 { window.border.width } else { 1.0 };
        Some((w, c))
    } else {
        Some((window.border.width, window.border.color.clone()))
    };
    let title = if window_present {
        m.get_one::<String>("title").map(|t| {
            let color = m
                .get_one::<String>("title_color")
                .cloned()
                .unwrap_or(window.title_config.color.clone());
            (t.clone(), color)
        })
    } else {
        // the title color is still validated by the renderer in the original
        if let (Some(_), Some(c)) = (m.get_one::<String>("title"), m.get_one::<String>("title_color")) {
            color::parse_hex(c);
        }
        None
    };

    // ---- code configuration ----
    let code_config = sc.code_config.clone().unwrap_or_default();
    let bc_cfg = code_config.breadcrumbs.clone().unwrap_or_default();
    let has_breadcrumbs = m.get_one::<bool>("has_breadcrumbs").copied().unwrap_or(false);
    let breadcrumbs = if has_breadcrumbs {
        match (&kind, &code_file_path) {
            (RenderKind::Code { .. }, Some(p)) => {
                let color = m.get_one::<String>("breadcrumbs_color").cloned().unwrap_or(bc_cfg.color.clone());
                Some((p.clone(), color))
            }
            _ => None,
        }
    } else {
        None
    };
    let line_numbers = if m.get_flag("has_line_number") {
        let start = m.get_one::<u32>("start_line_number").copied().unwrap_or(1);
        let color = m.get_one::<String>("line_number_color").cloned().unwrap_or_default();
        Some((start, color))
    } else {
        None
    };

    // ---- watermark ----
    let watermark = match sc.watermark.clone() {
        Some(w) => {
            let content = m.get_one::<String>("watermark").cloned().unwrap_or(w.content);
            let color = m.get_one::<String>("watermark_color").cloned().unwrap_or(w.color);
            Some((content, color))
        }
        None => m.get_one::<String>("watermark").map(|c| {
            let color = m
                .get_one::<String>("watermark_color")
                .cloned()
                .unwrap_or_else(|| "#ffffff".to_string());
            (c.clone(), color)
        }),
    };

    // ---- background ----
    let background = match sc.background.clone() {
        Some(config::Background::Solid(c)) => BackgroundSpec::Solid(c),
        Some(config::Background::Gradient(g)) => BackgroundSpec::Gradient {
            start: (g.start.x, g.start.y),
            end: (g.end.x, g.end.y),
            stops: g.stops.into_iter().map(|s| (s.position, s.color)).collect(),
        },
        None => return Err("`background` must be initialized".to_string()),
    };

    let opts = RenderOpts {
        kind,
        margin_x,
        margin_y,
        mac_window_bar,
        shadow_radius,
        shadow_color,
        border,
        radius: window.radius,
        title,
        breadcrumbs,
        line_numbers,
        highlights,
        watermark,
        background,
        scale: scale as f32,
    };

    let canvas = render::render(&opts);
    let png_bytes = png::encode_rgba(canvas.width as u32, canvas.height as u32, &canvas.to_rgba8());

    // ---- save ----
    if output == "clipboard" {
        return Err(input::CLIPBOARD_ERROR.to_string());
    }
    let data: Vec<u8> = if output.ends_with(".png") {
        png_bytes
    } else if output.ends_with(".svg") {
        format!(
            "<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><image href=\"data:image/png;base64,{}\"/></svg>",
            base64(&png_bytes)
        )
        .into_bytes()
    } else if output.ends_with(".html") {
        format!("<img src=\"data:image/png;base64,{}\" />", base64(&png_bytes)).into_bytes()
    } else {
        return Err("Unsupported output format".to_string());
    };
    std::fs::write(&output, data).map_err(|e| e.to_string())?;
    if !silent {
        messages::success(&format!("Snapshot saved to {} successful!", output));
    }
    if cfg.print_eggs {
        eggs::print_egg();
    }
    Ok(())
}
