    let png_bytes = png::encode_rgba(canvas.width as u32, canvas.height as u32, &canvas.to_rgba8());

    // ---- save ----
    if output == "clipboard" {
        return Err(input::CLIPBOARD_ERROR.to_string());
    }
    let data: Vec<u8> = if output.ends_with(".png") {
