    } else if output.ends_with(".html") {
        format!("<img src=\"data:image/png;base64,{}\" />", base64(&png_bytes)).into_bytes()
    } else {
        return Err("Unsupported output format".to_string());
    };
    std::fs::write(&output, data).map_err(|e| e.to_string())?;
